define "DXA Scan Order During Measurement Period":
  ( ( [ServiceRequest: "DXA (Dual energy Xray Absorptiometry) Scan"] ).isDiagnosticStudyOrder ( ) ) DXA
    where DXA.authoredOn.toInterval ( ) during "Measurement Period"
